// Despliegues INVENTADOS de un equipo en 14 días.
// commit y prod: horas desde el día 0 en que se hizo el commit y se puso en producción.
const despliegues = [
  { commit: 9,   prod: 11,  fallo: false },
  { commit: 20,  prod: 22,  fallo: false },
  { commit: 33,  prod: 36,  fallo: true, resuelto: 37 },
  { commit: 50,  prod: 51,  fallo: false },
  { commit: 70,  prod: 74,  fallo: false },
  { commit: 95,  prod: 96,  fallo: false },
  { commit: 118, prod: 121, fallo: true, resuelto: 125 },
  { commit: 140, prod: 141, fallo: false },
  { commit: 200, prod: 203, fallo: false },
  { commit: 260, prod: 262, fallo: false },
];
const dias = 14;
const mediana = a => { const s = [...a].sort((x, y) => x - y); const m = s.length >> 1; return s.length % 2 ? s[m] : (s[m - 1] + s[m]) / 2; };
const tiempos = despliegues.map(d => d.prod - d.commit);
const fallidos = despliegues.filter(d => d.fallo);
console.log('frecuencia de despliegue:', (despliegues.length / dias).toFixed(2), 'por dia (' + despliegues.length + ' en ' + dias + ' dias)');
console.log('tiempo de entrega (commit a produccion), mediana:', mediana(tiempos), 'h');
console.log('tasa de cambios fallidos:', (100 * fallidos.length / despliegues.length) + '%');
console.log('tiempo de recuperacion, mediana:', mediana(fallidos.map(d => d.resuelto - d.prod)), 'h');

// Interruptor con porcentaje: cada persona cae siempre en el mismo balde (0 a 99).
function balde(idUsuario, nombreFlag) {
  const texto = nombreFlag + ':' + idUsuario;
  let h = 2166136261;                     // FNV-1a de 32 bits
  for (let i = 0; i < texto.length; i++) {
    h ^= texto.charCodeAt(i);
    h = Math.imul(h, 16777619) >>> 0;
  }
  return h % 100;
}
const flags = { 'nuevo-calculo-envio': { activo: true, porcentaje: 10 } };
function estaPrendido(nombre, idUsuario) {
  const f = flags[nombre];
  return Boolean(f && f.activo && balde(idUsuario, nombre) < f.porcentaje);
}
const ids = Array.from({ length: 10000 }, (_, i) => 'u' + i);
for (const p of [1, 10, 50, 100]) {
  flags['nuevo-calculo-envio'].porcentaje = p;
  const n = ids.filter(id => estaPrendido('nuevo-calculo-envio', id)).length;
  console.log(p + '% pedido -> prende para ' + n + ' de 10000');
}
flags['nuevo-calculo-envio'].porcentaje = 10;
const antes = ids.filter(id => estaPrendido('nuevo-calculo-envio', id));
flags['nuevo-calculo-envio'].porcentaje = 20;
const despues = ids.filter(id => estaPrendido('nuevo-calculo-envio', id));
console.log('al subir de 10% a 20%, los del 10% siguen adentro:', antes.every(id => despues.includes(id)));
flags['nuevo-calculo-envio'].activo = false;
console.log('interruptor apagado ->', ids.filter(id => estaPrendido('nuevo-calculo-envio', id)).length, 'personas');
